// Gerado por scripts/gerar-roteiros.mjs a partir de atual.html e nova.html. Não edite à mão.
export const ROTEIRO_ATUAL_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Roteiro Atual da Call</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Barlow+Condensed:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap\">\n<style>\n/* Análise do roteiro que o time usa hoje: placar, a call como acontece, os números de 11 calls gravadas e os erros que se repetem. */\n:root {\n  color-scheme: dark;\n  --bg: #0a0a0a;\n  --bg-2: #0b0e0d;\n  --fg: #f6f6f6;\n  --muted: rgba(246, 246, 246, 0.68);\n  --faint: rgba(246, 246, 246, 0.42);\n  --line: rgba(255, 255, 255, 0.10);\n  --card: rgba(255, 255, 255, 0.04);\n  --teal: #2dd4bf;\n  --teal-ink: #052e2a;\n  --teal-wash: rgba(45, 212, 191, 0.07);\n  --teal-edge: rgba(45, 212, 191, 0.40);\n  --red: #ff2e5f;\n  --red-band: #e2063c;\n  --red-wash: rgba(255, 46, 95, 0.08);\n  --red-edge: rgba(255, 46, 95, 0.34);\n  --amber: #f5b942;\n  --amber-wash: rgba(245, 185, 66, 0.08);\n  --amber-edge: rgba(245, 185, 66, 0.36);\n  --display: \"Bebas Neue\", \"Oswald\", \"Arial Narrow\", Impact, sans-serif;\n  --body: \"Barlow Condensed\", \"Roboto Condensed\", \"Arial Narrow\", sans-serif;\n  --ui: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody { margin: 0; background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 19px; line-height: 1.55; -webkit-font-smoothing: antialiased; }\n.wrap { width: 100%; max-width: 1180px; margin: 0 auto; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }\n@media (min-width: 900px) { .wrap { padding-left: max(40px, env(safe-area-inset-left, 0px)); padding-right: max(40px, env(safe-area-inset-right, 0px)); } }\n.t { color: var(--teal); }\n.r { color: var(--red); }\nstrong { font-weight: 700; color: var(--fg); }\na { color: var(--teal); }\na:focus-visible { outline: 2px solid var(--teal); outline-offset: 3px; border-radius: 6px; }\n\n.band { background: var(--red-band); color: #fff; text-align: center; font-family: var(--display); letter-spacing: 0.32em; font-size: 15px; padding-block: 10px; }\n.band a { color: #fff; }\n\n.hero { border-bottom: 1px solid var(--line); background: radial-gradient(900px 520px at 85% 0%, rgba(226, 6, 60, 0.16), transparent 60%), radial-gradient(700px 480px at 0% 100%, rgba(45, 212, 191, 0.10), transparent 60%), var(--bg-2); }\n.hero .wrap { padding-block: 52px 40px; display: grid; gap: 22px; }\n.brand { font-family: var(--display); letter-spacing: 0.18em; font-size: 18px; color: var(--muted); }\n.pills { display: flex; flex-wrap: wrap; gap: 10px; }\n.pill { display: inline-flex; align-items: center; gap: 8px; font-family: var(--display); letter-spacing: 0.16em; font-size: 14px; padding: 6px 14px; border-radius: 999px; border: 1px solid var(--red-edge); color: var(--red); background: var(--red-wash); text-decoration: none; }\n.pill.teal { border-color: var(--teal-edge); color: var(--teal); background: var(--teal-wash); }\nh1 { font-family: var(--display); font-weight: 400; font-size: clamp(54px, 8vw, 104px); line-height: 0.9; letter-spacing: 0.02em; margin: 0; text-wrap: balance; }\n.lede { max-width: 66ch; font-size: 21px; color: var(--muted); margin: 0; }\n\n.score { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border: 1px solid var(--line); border-radius: 16px; background: var(--card); overflow: hidden; }\n.score div { padding: 16px 18px; display: grid; gap: 2px; min-width: 0; }\n.score div + div { border-left: 1px solid var(--line); }\n.score b { font-family: var(--display); font-weight: 400; font-size: 52px; line-height: 0.95; font-variant-numeric: tabular-nums; }\n.score span { font-family: var(--ui); font-size: 12.5px; color: var(--muted); line-height: 1.35; }\n.note { font-family: var(--ui); font-size: 12.5px; color: var(--faint); margin: 0; }\n\nsection.block { padding-block: 52px 8px; display: grid; gap: 20px; }\nsection.block + section.block { border-top: 1px solid var(--line); }\n.kicker { font-family: var(--display); letter-spacing: 0.2em; font-size: 15px; color: var(--faint); }\nh2 { font-family: var(--display); font-weight: 400; font-size: clamp(38px, 4.4vw, 58px); line-height: 0.95; letter-spacing: 0.02em; margin: 2px 0 0; text-wrap: balance; }\n.intro { margin: 0; max-width: 68ch; font-size: 20px; color: var(--muted); }\n\n/* a call como acontece */\n.flow { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; counter-reset: f; }\n.flow li { counter-increment: f; padding: 16px; border-radius: 14px; border: 1px solid var(--line); background: var(--card); display: grid; gap: 6px; align-content: start; min-width: 0; }\n.flow li::before { content: counter(f); font-family: var(--display); font-size: 30px; line-height: 1; color: var(--faint); }\n.flow b { font-family: var(--display); font-weight: 400; font-size: 23px; letter-spacing: 0.03em; line-height: 1; }\n.flow span { font-size: 17px; color: var(--muted); line-height: 1.35; }\n.flow .tempo { font-family: var(--ui); font-size: 12px; color: var(--faint); }\n.flow li.bad { border-color: var(--red-edge); background: var(--red-wash); }\n.flow li.bad::before { color: var(--red); }\n\n/* a call que vendeu */\n.flow li.good { border-color: var(--teal-edge); background: var(--teal-wash); }\n.flow li.good::before { color: var(--teal); }\n.score.win b { color: var(--teal); }\n.quotes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n.quotes blockquote { margin: 0; padding: 14px 18px; border-left: 3px solid var(--teal-edge); background: var(--teal-wash); border-radius: 0 12px 12px 0; font-size: 19.5px; font-style: italic; color: var(--fg); line-height: 1.4; }\n.quotes cite { display: block; margin-top: 8px; font-family: var(--ui); font-style: normal; font-size: 12.5px; color: var(--faint); }\n.atencao { margin: 0; padding: 14px 18px; border-radius: 14px; border: 1px solid var(--amber-edge); background: var(--amber-wash); font-size: 18.5px; color: var(--muted); line-height: 1.42; }\n.atencao b { font-family: var(--display); font-weight: 400; letter-spacing: 0.08em; color: var(--amber); }\n\n/* barras de aderência */\n.bars { display: grid; gap: 10px; }\n.bar { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr) 70px; gap: 16px; align-items: center; padding: 12px 16px; border-radius: 12px; border: 1px solid var(--line); background: var(--card); }\n.bar .lbl { font-size: 19px; line-height: 1.3; min-width: 0; }\n.bar .lbl small { display: block; font-family: var(--ui); font-size: 12.5px; color: var(--faint); margin-top: 2px; }\n.track { height: 12px; border-radius: 999px; background: rgba(255, 255, 255, 0.07); overflow: hidden; }\n.fill { height: 100%; border-radius: 999px; }\n.fill.good { background: var(--teal); }\n.fill.bad { background: var(--red); }\n.fill.zero { background: transparent; }\n.bar .num { font-family: var(--display); font-size: 30px; line-height: 1; text-align: right; font-variant-numeric: tabular-nums; }\n.bar.want .num { color: var(--red); }\n.bar.avoid .num { color: var(--red); }\n.legend { display: flex; flex-wrap: wrap; gap: 8px 20px; font-family: var(--ui); font-size: 12.5px; color: var(--muted); }\n.legend i { display: inline-block; width: 10px; height: 10px; border-radius: 3px; margin-right: 6px; vertical-align: -1px; }\n\n/* erros */\n.errs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; counter-reset: e; }\n.err { counter-increment: e; padding: 20px 22px; border-radius: 16px; border: 1px solid var(--line); background: var(--card); display: grid; gap: 10px; align-content: start; min-width: 0; }\n.err header { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 12px; align-items: baseline; }\n.err header::before { content: counter(e); font-family: var(--display); font-size: 34px; line-height: 1; color: var(--red); }\n.err h3 { margin: 0; font-family: var(--display); font-weight: 400; font-size: 27px; letter-spacing: 0.03em; line-height: 1; }\n.sev { font-family: var(--ui); font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; padding: 3px 8px; border-radius: 999px; white-space: nowrap; }\n.sev.alta { color: var(--red); border: 1px solid var(--red-edge); background: var(--red-wash); }\n.sev.media { color: var(--amber); border: 1px solid var(--amber-edge); background: var(--amber-wash); }\n.err p { margin: 0; font-size: 19px; color: var(--muted); line-height: 1.42; }\n.err blockquote { margin: 0; padding: 10px 14px; border-left: 3px solid var(--red-edge); background: rgba(255, 255, 255, 0.025); border-radius: 0 10px 10px 0; font-size: 18.5px; font-style: italic; color: var(--fg); }\n.err .fix { font-size: 18px; color: var(--fg); border-top: 1px solid var(--line); padding-top: 10px; }\n.err .fix::before { content: \"O certo: \"; font-family: var(--display); letter-spacing: 0.08em; color: var(--teal); }\n.err.wide { grid-column: 1 / -1; }\n\n/* tabelas */\n.tablewrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 14px; }\ntable { width: 100%; border-collapse: collapse; font-family: var(--ui); font-size: 14px; min-width: 620px; }\nth, td { text-align: left; padding: 11px 14px; border-bottom: 1px solid var(--line); vertical-align: top; }\nth { font-weight: 600; color: var(--faint); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }\ntr:last-child td { border-bottom: 0; }\ntd.no { color: var(--red); font-weight: 600; }\ntd.ok { color: var(--teal); font-weight: 600; }\n\n.works { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n.works div { padding: 16px 18px; border-radius: 14px; border: 1px solid var(--teal-edge); background: var(--teal-wash); display: grid; gap: 6px; align-content: start; min-width: 0; }\n.works b { font-family: var(--display); font-weight: 400; font-size: 24px; letter-spacing: 0.03em; line-height: 1; color: var(--teal); }\n.works span { font-size: 17.5px; color: var(--muted); line-height: 1.38; }\n\n.cta { display: flex; flex-wrap: wrap; gap: 12px; align-items: center; padding: 22px; border-radius: 16px; border: 1px solid var(--teal-edge); background: var(--teal-wash); }\n.cta p { margin: 0; font-size: 20px; flex: 1 1 320px; }\n.btn { font-family: var(--display); letter-spacing: 0.14em; font-size: 17px; padding: 10px 18px; border-radius: 999px; background: var(--teal); color: var(--teal-ink); text-decoration: none; white-space: nowrap; }\n\nfooter { border-top: 1px solid var(--line); margin-top: 52px; }\nfooter .wrap { padding-block: 24px 40px; font-family: var(--ui); font-size: 12.5px; color: var(--faint); display: flex; flex-wrap: wrap; gap: 8px 24px; justify-content: space-between; }\n\n@media (max-width: 980px) {\n  .flow { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .works { grid-template-columns: minmax(0, 1fr); }\n}\n@media (max-width: 720px) {\n  body { font-size: 18px; }\n  .score { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .score div:nth-child(3) { border-left: 0; }\n  .score div:nth-child(n+3) { border-top: 1px solid var(--line); }\n  .errs, .flow, .quotes { grid-template-columns: minmax(0, 1fr); }\n  .bar { grid-template-columns: minmax(0, 1fr) 56px; }\n  .bar .track { grid-column: 1 / -1; grid-row: 2; }\n}\n@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }\n</style>\n</head>\n<body>\n\n<div class=\"band\">ANÁLISE INTERNA · TIME COMERCIAL</div>\n\n<header class=\"hero\">\n  <div class=\"wrap\">\n    <div class=\"brand\">CANAL DO ANFITRIÃO</div>\n    <div class=\"pills\">\n      <span class=\"pill\">Como a call é feita hoje</span>\n      <a class=\"pill teal\" href=\"#venda\">A call que vendeu ↓</a>\n    </div>\n    <h1>O roteiro<br><span class=\"r\">de hoje</span></h1>\n    <p class=\"lede\">O que acontece de verdade nas calls, montado a partir de <strong>15 calls gravadas</strong> (3 de 03/11 e 12 de 04 a 11/11) e das conversas de WhatsApp depois delas.</p>\n    <div class=\"score\" aria-label=\"Placar de 09 a 11/11\">\n      <div><b>23</b><span>calls marcadas de 09 a 11/11 (em 11/11, até a das 14h)</span></div>\n      <div><b class=\"r\">10</b><span>faltaram (43%), nenhuma resgatada pelo sistema</span></div>\n      <div><b>13</b><span>aconteceram</span></div>\n      <div><b class=\"t\">1</b><span>Black vendida na própria call, a do Flávio em 11/11 (nenhum A5E; mais 1 curso de Booking)</span></div>\n    </div>\n    <p class=\"note\">Em 11/11, das 4 calls até as 14h, 3 aconteceram, e a das 14h, do Flávio, fechou a Black na própria call (<a href=\"#venda\">veja abaixo</a>). O Gerson (11h30) não conseguiu entrar no Teams. As calls das 14h30 em diante entram aqui quando a gravação chegar. As outras vendas do dia vieram por mensagem.</p>\n  </div>\n</header>\n\n<main class=\"wrap\">\n\n  <section class=\"block\" id=\"venda\">\n    <div><span class=\"kicker\">11/11, 14h · Flávio com Breno Lima</span><h2>A call que <span class=\"t\">vendeu</span></h2></div>\n    <p class=\"intro\">Black Friday Vitalícia pelo preço de tabela, em 12x no cartão (R$ 10.796,52). O lead chegou quente: veio da live, já pensava em comprar e tinha uma trava só, o medo de pagar R$ 8 mil e não se adaptar ao curso, que o Téo anotou na ficha antes da call. O que o Flávio fez com isso:</p>\n    <div class=\"score win\" aria-label=\"A call em números\">\n      <div><b>26</b><span>minutos de call</span></div>\n      <div><b>0</b><span>desconto ou bônus extra: preço de tabela</span></div>\n      <div><b>3</b><span>vezes a garantia de 14 dias, sempre ligada à trava do lead</span></div>\n      <div><b>21</b><span>minutos do link ao pagamento</span></div>\n    </div>\n    <ol class=\"flow\">\n      <li class=\"good\"><span class=\"tempo\">0–2 min</span><b>Abre pelo lead</b><span>\"Me passa um pouco mais do seu projeto, fica à vontade.\" O lead conta dos 5 apartamentos, do plano de ir para Brasília e da dúvida dele.</span></li>\n      <li class=\"good\"><span class=\"tempo\">2–4 min</span><b>Pergunta o que já tentou</b><span>\"Algum curso foi do Rômulo?\" e \"qual oferta mais te chamou atenção?\". Descobre o medo: pagar por conteúdo que ele já viu.</span></li>\n      <li class=\"good\"><span class=\"tempo\">4–14 min</span><b>Recomenda pelo caso</b><span>\"O A5E é para quem começa; o seu caso é o Gigantes.\" Ainda é tour de módulos, mas cada um ligado à gestão para terceiros e a Brasília.</span></li>\n      <li class=\"good\"><span class=\"tempo\">15–17 min</span><b>Garantia na trava</b><span>O lead diz que tem medo de não se adaptar à didática. A resposta: 14 dias, o dobro do comum, 100% de volta.</span></li>\n      <li class=\"good\"><span class=\"tempo\">17–19 min</span><b>Comunidade</b><span>O lead diz que o grupo de WhatsApp é o que mais vale para ele. O Flávio aprofunda: 350 gestores e o Rômulo por perto, por 4 anos.</span></li>\n      <li class=\"good\"><span class=\"tempo\">20–21 min</span><b>Garantia de novo</b><span>\"Se não for o que a gente conversou, fala direto comigo que eu aciono o reembolso.\" O lead relaxa.</span></li>\n      <li class=\"good\"><span class=\"tempo\">21–24 min</span><b>Pede o fechamento</b><span>\"Fez sentido para você? Teria interesse?\" Com o sim: \"cartão ou boleto?\".</span></li>\n      <li class=\"good\"><span class=\"tempo\">24 min em diante</span><b>Link na hora</b><span>O lead quer falar com a mãe antes. O link vai pelo WhatsApp mesmo assim, e 18 min depois: \"Deu tudo certo?\". Pago às 14h46.</span></li>\n    </ol>\n    <div class=\"quotes\">\n      <blockquote>\"A gente confia nisso, que a gente te dá 14 dias de garantia. A maioria é 7 dias, né? A gente deixa 14 dias ou a gente devolve 100% do seu investimento.\"<cite>Flávio, aos 15 minutos</cite></blockquote>\n      <blockquote>\"Então assim eu fico bem mais tranquilo de experimentar, e acredito que vai dar tudo certo.\"<cite>Breno Lima, aos 20 minutos</cite></blockquote>\n    </div>\n    <p class=\"atencao\"><b>Um deslize:</b> no fim, \"esse investimento vai se pagar, você vai ver\" é promessa de resultado. Não fazia falta: o lead já tinha decidido pela garantia.</p>\n  </section>\n\n  <section class=\"block\" id=\"fluxo\">\n    <div><span class=\"kicker\">A call como acontece</span><h2>Oito partes, <span class=\"r\">nesta ordem</span></h2></div>\n    <p class=\"intro\">Os três vendedores seguem a mesma sequência. Marcada como papo de 20 minutos, a call dura de 25 a 45. O lead fala pouco e ouve muito: a apresentação dos módulos ocupa metade do tempo.</p>\n    <ol class=\"flow\">\n      <li><span class=\"tempo\">0–2 min</span><b>Abertura</b><span>\"Sou do time comercial do Rômulo, vou entender seu cenário.\"</span></li>\n      <li><span class=\"tempo\">2–5 min</span><b>2 a 5 perguntas</b><span>Sobre o imóvel e a experiência. Ninguém pergunta meta, prazo ou o que preocupa.</span></li>\n      <li class=\"bad\"><span class=\"tempo\">3–8 min</span><b>\"Conhece o Rômulo?\"</b><span>Vem o currículo: imóveis, locações, alunos. Com números diferentes a cada vendedor.</span></li>\n      <li class=\"bad\"><span class=\"tempo\">4–7 min</span><b>\"Dois sentimentos\"</b><span>\"No fim você vai ter dois sentimentos…\"</span></li>\n      <li class=\"bad\"><span class=\"tempo\">15–30 min</span><b>Tour pelos módulos</b><span>Hospitalidade, PriceLabs, OwnerPro, IA, imposto, terceiros, AirCover. A comunidade aparece no fim, como bônus.</span></li>\n      <li><span class=\"tempo\">antes do preço</span><b>\"Ficou alguma dúvida?\"</b><span>Checagem genérica, sem resumo do caso do lead.</span></li>\n      <li class=\"bad\"><span class=\"tempo\">21–37 min</span><b>Preço</b><span>Já com desconto e bônus, sem o lead ter pedido. Cada vendedor parte de um valor.</span></li>\n      <li><span class=\"tempo\">23–39 min</span><b>Pedido</b><span>\"Podemos seguir com a inscrição?\" Depois do \"vou pensar\", proposta por WhatsApp e espera.</span></li>\n    </ol>\n  </section>\n\n  <section class=\"block\" id=\"numeros\">\n    <div><span class=\"kicker\">12 calls gravadas de 04 a 11/11</span><h2>O que aparece <span class=\"r\">e o que não aparece</span></h2></div>\n    <p class=\"intro\">Contagem pelas falas do vendedor nas transcrições do Teams (10 calls de venda, 9 de A5E e 1 da Black; as outras 2 foram de aluna com dúvida e uma gravação sem o nome do vendedor). Erro de transcrição pode mudar um número ou outro, não o quadro.</p>\n    <div class=\"legend\"><span><i style=\"background: var(--red)\"></i>vermelho = deveria acontecer e não acontece, ou não deveria e acontece</span></div>\n    <div class=\"bars\">\n      <div class=\"bar want\"><span class=\"lbl\">Cita a garantia de 14 dias<small>a resposta mais forte pro \"vou pensar\" e pro cônjuge; a única call que citou foi a que vendeu</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 8%\"></div></div><span class=\"num\">1/12</span></div>\n      <div class=\"bar want\"><span class=\"lbl\">Aprofunda o caso do lead<small>\"me conta mais\", rotular o problema, \"o que você já tentou?\"</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 8%\"></div></div><span class=\"num\">1/12</span></div>\n      <div class=\"bar want\"><span class=\"lbl\">Usa o cupom de R$ 2.797, o degrau certo da escada<small>nas calls de A5E</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 11%\"></div></div><span class=\"num\">1/9</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Dá o curso de Booking de bônus<small>nas calls de A5E; só deveria sair se o lead pedir mais desconto depois do R$ 2.497</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 78%\"></div></div><span class=\"num\">7/9</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Faz o tour pelos módulos</span><div class=\"track\"><div class=\"fill bad\" style=\"width: 70%\"></div></div><span class=\"num\">7/10</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Desce para R$ 2.497 (desconto de R$ 500) sem objeção concreta<small>nas calls de A5E</small></span><div class=\"track\"><div class=\"fill bad\" style=\"width: 44%\"></div></div><span class=\"num\">4/9</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Pergunta \"você conhece o Rômulo?\"</span><div class=\"track\"><div class=\"fill bad\" style=\"width: 40%\"></div></div><span class=\"num\">4/10</span></div>\n      <div class=\"bar avoid\"><span class=\"lbl\">Faz o combinado dos \"dois sentimentos\"</span><div class=\"track\"><div class=\"fill bad\" style=\"width: 30%\"></div></div><span class=\"num\">3/10</span></div>\n    </div>\n  </section>\n\n  <section class=\"block\" id=\"erros\">\n    <div><span class=\"kicker\">Os erros que se repetem</span><h2>Onde a venda <span class=\"r\">escapa</span></h2></div>\n    <div class=\"errs\">\n      <article class=\"err\">\n        <header><h3>O preço cai antes da objeção</h3><span class=\"sev alta\">alto</span></header>\n        <p>O lead nem reclamou do preço e já recebe R$ 2.497 com o Booking de presente. Quando a objeção chega, não sobra degrau: o vendedor inventa outro.</p>\n        <blockquote>\"O Anfitrião custa 3 mil reais, só que como a gente tá em Black Friday eu consigo disponibilizar 500 reais de desconto… e o curso de Booking sem custo adicional.\" (11/11, lead sem nenhuma objeção)</blockquote>\n        <p class=\"fix\">R$ 2.997 sempre primeiro. R$ 2.797 só na objeção de preço, R$ 2.497 só com trava concreta, Booking só se pedir mais.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Bônus de presente</h3><span class=\"sev alta\">alto</span></header>\n        <p>O bônus vira agrado em vez de ferramenta de fechamento. Sai antes de o lead pedir, e às vezes com justificativa pessoal.</p>\n        <blockquote>\"Vou te ofertar como bônus o curso de Booking, por você ter aceito esse bate-papo. Eu gostei muito de você.\" (10/11)</blockquote>\n        <p class=\"fix\">O bônus é o último degrau da escada, não o primeiro.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>A garantia quase nunca aparece</h3><span class=\"sev alta\">alto</span></header>\n        <p>Apareceu em 1 de 12 calls, justo na que vendeu: era a trava do lead, e ele pagou 21 minutos depois do link. Em 03/11 ela só apareceu no WhatsApp, horas depois, quando o cônjuge já tinha achado caro. É o argumento que tira o risco da mesa.</p>\n        <p class=\"fix\">\"Você tem 14 dias de garantia. A lei dá 7, a gente dá 14: é o dobro. Se não for o que eu te disse, devolvemos 100%.\"</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Promessa de ganho</h3><span class=\"sev alta\">alto</span></header>\n        <p>Número de faturamento e \"certeza\" de resultado usados como argumento. Além de proibido, vira problema se o aluno não chegar lá.</p>\n        <blockquote>\"Um de 19 metros quadrados… você consegue faturar com ele aí de 15 a 17, 18 mil.\" (10/11)</blockquote>\n        <blockquote>\"O curso realmente promete uma diária a mais, e isso é certeza que você vai ter.\" (10/11)</blockquote>\n        <p class=\"fix\">Nada de promessa de ganho nem de faturamento. A prova é o caso de aluno, contado como história.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Apresenta antes de entender</h3><span class=\"sev alta\">alto</span></header>\n        <p>Duas a cinco perguntas sobre o imóvel e depois 15 a 30 minutos de módulos. O vendedor não sabe a meta, o prazo nem o medo do lead quando chega no preço, então não tem com o que ligar o preço ao caso dele.</p>\n        <p class=\"fix\">Perguntar e resumir o caso (\"hoje você…, quer chegar em…, o que está no caminho é… É isso?\") antes de mostrar qualquer coisa.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Condições que não existem</h3><span class=\"sev alta\">alto</span></header>\n        <p>Cada vendedor cria um preço. O lead compara, e quem pagou mais se sente enganado.</p>\n        <blockquote>\"Os 2 [ingressos do Encontro], né, 697… a gente vê se consegue algum cupomzinho de desconto pra vocês.\" (11/11; a pré-venda é R$ 997 Standard e R$ 1.397 VIP)</blockquote>\n        <p>Também apareceram: cupom de R$ 800 (R$ 2.297), preço de aluno da Black para quem não é aluno, consultoria que está pausada, \"a esposa assiste no mesmo acesso\".</p>\n        <p class=\"fix\">Só a escada e as condições da tabela. Fora disso, o vendedor diz que confirma com o time antes de prometer.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>O cônjuge fica de fora</h3><span class=\"sev media\">médio</span></header>\n        <p>O cônjuge aparece em 6 das 12 calls, quase sempre na saída: \"vou ver com meu marido\", \"minha mulher está ocupada\". Ninguém convidou o cônjuge para a call.</p>\n        <p class=\"fix\">Chamar o cônjuge já na marcação. Se não veio, tratar a objeção na hora e fechar com a garantia de 14 dias.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>Currículo do Rômulo no lugar da conversa</h3><span class=\"sev media\">médio</span></header>\n        <p>\"Você conhece o Rômulo?\" abre um bloco de números que muda a cada vendedor (80, 89 imóveis; 11 mil locações), e em 03/11 entraram números da empresa, que nunca podem ser citados.</p>\n        <p class=\"fix\">Uma frase só: \"Começou em 2016 alugando um quartinho… hoje administra mais de 70 imóveis.\"</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>\"Vou pensar\" sem pergunta e sem data</h3><span class=\"sev media\">médio</span></header>\n        <p>Diante do \"vou pensar\", o vendedor aceita e manda proposta por WhatsApp. Em 3 das 10 calls de venda a saída foi sem data de retorno.</p>\n        <p class=\"fix\">\"Você acha que vai melhor com isso do que sem? O que você tem medo que aconteça?\" e, se não fechar, retorno com dia e hora.</p>\n      </article>\n      <article class=\"err\">\n        <header><h3>A comunidade vira bônus</h3><span class=\"sev media\">médio</span></header>\n        <p>A comunidade de WhatsApp com o Rômulo aparece entre os minutos 15 e 24, no fim da lista de módulos. É o que o YouTube não tem, e chega quando o lead já cansou.</p>\n        <p class=\"fix\">Chamar o A5E de comunidade desde o começo e falar dela no começo da apresentação, não no fim.</p>\n      </article>\n      <article class=\"err wide\">\n        <header><h3>Quase metade falta, e ninguém resgata</h3><span class=\"sev alta\">alto</span></header>\n        <p>9 das 19 calls de 09 e 10/11 tiveram falta. Quem marcou para o mesmo dia apareceu (2 de 2); com 1 dia de antecedência, 4 de 6; com 2 ou 3 dias, 0 de 2. Das faltas, 3 foram remarcadas por fora do sistema e 6 ficaram sem contato. A falta não é erro do vendedor, mas é a maior perda do funil hoje: cada falta é uma call que nem chega ao roteiro.</p>\n        <p>Em 11/11 apareceu outra causa: o Gerson baixou o app do Teams na hora da call, escreveu às 11h40 \"não sei bem o que fazer\" e a primeira resposta veio às 12h14, quando a call já tinha passado.</p>\n        <p class=\"fix\">Oferecer horários mais próximos, responder na hora quem escreve que não consegue entrar e remarcar quem faltou pelo próprio sistema, com o mesmo vendedor.</p>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"block\" id=\"preco\">\n    <div><span class=\"kicker\">Preço, cupom e bônus</span><h2>Quatro preços <span class=\"r\">para o mesmo curso</span></h2></div>\n    <p class=\"intro\">O A5E custa R$ 2.997 na tabela. Nas calls e no WhatsApp, entre 03 e 11/11, ele saiu assim:</p>\n    <div class=\"tablewrap\">\n      <table>\n        <thead><tr><th>Preço oferecido</th><th>Quando apareceu</th><th>Com bônus?</th><th>Bate com a escada?</th></tr></thead>\n        <tbody>\n          <tr><td>R$ 2.997 ou 12x R$ 299,70</td><td>Preço de partida de um dos vendedores</td><td>Booking e Sublocação citados na apresentação</td><td class=\"ok\">Sim, é o primeiro degrau</td></tr>\n          <tr><td>R$ 2.797 (cupom)</td><td>1 call em 9</td><td>Booking junto</td><td class=\"no\">Degrau certo, bônus antes da hora</td></tr>\n          <tr><td>R$ 2.497 ou 12x R$ 249,70</td><td>Preço de partida de dois vendedores, sem objeção</td><td>Booking (às vezes Booking ou Sublocação, à escolha)</td><td class=\"no\">Não: pula dois degraus</td></tr>\n          <tr><td>R$ 2.297 (cupom de R$ 800)</td><td>WhatsApp, depois do \"vou ver com meu marido\"</td><td>—</td><td class=\"no\">Não existe na escada</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section class=\"block\" id=\"funciona\">\n    <div><span class=\"kicker\">O que já funciona</span><h2>Para <span class=\"t\">manter</span></h2></div>\n    <div class=\"works\">\n      <div><b>Link na própria call</b><span>Na call que vendeu, o Flávio perguntou \"cartão ou boleto?\", mandou o link antes de desligar e voltou 18 minutos depois com \"Deu tudo certo?\". O pagamento entrou em seguida.</span></div>\n      <div><b>Retorno com data</b><span>Em 5 das 10 calls de venda a saída teve dia marcado (ex.: \"amanhã às 10h, depois de falar com a esposa\"). É assim que o lead volta.</span></div>\n      <div><b>Pagamento explicado</b><span>Parcelamento em 10 de 12 calls e boleto em 7. Ninguém sai da call sem saber como pagaria.</span></div>\n      <div><b>A IA como diferencial</b><span>A assistente que monta o plano de estudo e responde no grupo foi mostrada em 6 calls, ao vivo, e o lead reage bem.</span></div>\n    </div>\n  </section>\n\n</main>\n\n<footer>\n  <div class=\"wrap\">\n    <span>Fontes: transcrições das calls no Teams (03 a 11/11/2026), conversas de WhatsApp e o placar do sistema de calls. Atualizado em 11/11/2026.</span>\n    <span>Canal do Anfitrião · uso interno do time comercial</span>\n  </div>\n</footer>\n\n</body>\n</html>\n";
export const ROTEIRO_NOVA_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Roteiro Novo da Call</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Barlow+Condensed:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap\">\n<style>\n/* Layout: guia de bolso da call no padrão do Encontro dos Anfitriões. Menu fixo à esquerda com as 8 etapas na ordem da call; à direita, cada etapa com as falas em destaque, o que fazer e o que não fazer. */\n:root {\n  color-scheme: dark;\n  --bg: #0a0a0a;\n  --bg-2: #0b0e0d;\n  --fg: #f6f6f6;\n  --muted: rgba(246, 246, 246, 0.68);\n  --faint: rgba(246, 246, 246, 0.42);\n  --line: rgba(255, 255, 255, 0.10);\n  --card: rgba(255, 255, 255, 0.04);\n  --teal: #2dd4bf;\n  --teal-ink: #052e2a;\n  --teal-wash: rgba(45, 212, 191, 0.07);\n  --teal-edge: rgba(45, 212, 191, 0.40);\n  --red: #ff2e5f;\n  --red-band: #e2063c;\n  --red-wash: rgba(255, 46, 95, 0.07);\n  --red-edge: rgba(255, 46, 95, 0.32);\n  --display: \"Bebas Neue\", \"Oswald\", \"Arial Narrow\", Impact, sans-serif;\n  --body: \"Barlow Condensed\", \"Roboto Condensed\", \"Arial Narrow\", sans-serif;\n  --ui: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody { margin: 0; background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 19px; line-height: 1.55; -webkit-font-smoothing: antialiased; }\nbody::before { content: \"\"; position: fixed; inset: 0 0 auto; height: env(safe-area-inset-top, 0px); z-index: 10; background: var(--bg); }\n.wrap { width: 100%; max-width: 1280px; margin: 0 auto; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }\n@media (min-width: 900px) { .wrap { padding-left: max(40px, env(safe-area-inset-left, 0px)); padding-right: max(40px, env(safe-area-inset-right, 0px)); } }\n.t { color: var(--teal); }\nstrong { font-weight: 700; color: var(--fg); }\na { color: inherit; }\na:focus-visible, button:focus-visible { outline: 2px solid var(--teal); outline-offset: 3px; border-radius: 6px; }\n\n.band { background: var(--red-band); color: #fff; text-align: center; font-family: var(--display); letter-spacing: 0.32em; font-size: 15px; padding-block: 10px; }\n\n/* hero */\n.hero { border-bottom: 1px solid var(--line); background: radial-gradient(900px 520px at 85% 0%, rgba(45, 212, 191, 0.16), transparent 60%), radial-gradient(700px 480px at 0% 100%, rgba(226, 6, 60, 0.12), transparent 60%), var(--bg-2); }\n.hero .wrap { padding-block: 56px 44px; display: grid; gap: 26px; }\n.brand { font-family: var(--display); letter-spacing: 0.18em; font-size: 18px; color: var(--muted); }\n.pills { display: flex; flex-wrap: wrap; gap: 10px; }\n.pill { display: inline-flex; align-items: center; gap: 8px; font-family: var(--display); letter-spacing: 0.16em; font-size: 14px; padding: 6px 14px; border-radius: 999px; border: 1px solid var(--teal-edge); color: var(--teal); background: var(--teal-wash); }\n.pill.red { border-color: transparent; background: var(--red-band); color: #fff; }\n.pill .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--teal); }\nh1 { font-family: var(--display); font-weight: 400; font-size: clamp(56px, 8.4vw, 112px); line-height: 0.9; letter-spacing: 0.02em; margin: 0; text-wrap: balance; }\n.lede { max-width: 64ch; font-size: 21px; color: var(--muted); margin: 0; }\n.closer { display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); border: 1px solid var(--line); border-radius: 16px; background: var(--card); overflow: hidden; }\n.closer a { text-decoration: none; padding: 14px 14px 16px; display: grid; gap: 4px; min-width: 0; transition: background 0.2s; }\n.closer a + a { border-left: 1px solid var(--line); }\n.closer a:hover { background: var(--teal-wash); }\n.closer b { font-family: var(--display); font-weight: 400; font-size: 34px; line-height: 1; color: var(--teal); }\n.closer span { font-family: var(--display); font-size: 17px; letter-spacing: 0.04em; line-height: 1.05; }\n\n/* corpo com menu */\n.layout { display: grid; grid-template-columns: 236px minmax(0, 1fr); gap: 48px; padding-block: 40px 24px; }\n.nav { position: sticky; top: calc(env(safe-area-inset-top, 0px) + 24px); align-self: start; display: grid; gap: 2px; }\n.nav .label { font-family: var(--display); letter-spacing: 0.2em; font-size: 14px; color: var(--faint); margin-bottom: 8px; }\n.nav a { display: grid; grid-template-columns: 30px minmax(0, 1fr); align-items: center; gap: 10px; padding: 8px 10px; border-radius: 10px; text-decoration: none; color: var(--muted); font-family: var(--display); font-size: 19px; letter-spacing: 0.04em; border: 1px solid transparent; }\n.nav a b { font-weight: 400; color: var(--faint); font-size: 22px; }\n.nav a:hover { color: var(--fg); }\n.nav a.on { background: var(--teal-wash); border-color: var(--teal-edge); color: var(--fg); }\n.nav a.on b { color: var(--teal); }\n.nav .rule { margin-top: 18px; padding: 14px; border-radius: 12px; border: 1px solid var(--line); font-family: var(--ui); font-size: 13px; color: var(--muted); line-height: 1.45; }\n.nav .rule strong { color: var(--teal); }\n\n/* etapas */\n.stage { padding-block: 8px 56px; scroll-margin-top: 24px; display: grid; gap: 22px; }\n.stage + .stage { border-top: 1px solid var(--line); padding-top: 48px; }\n.stage-head { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 20px; align-items: end; }\n.num { font-family: var(--display); font-size: 104px; line-height: 0.8; color: var(--teal); letter-spacing: 0.01em; }\n.kicker { font-family: var(--display); letter-spacing: 0.2em; font-size: 15px; color: var(--faint); }\nh2 { font-family: var(--display); font-weight: 400; font-size: clamp(40px, 4.4vw, 62px); line-height: 0.95; letter-spacing: 0.02em; margin: 2px 0 0; text-wrap: balance; }\n.intro { margin: 0; max-width: 64ch; font-size: 20px; color: var(--muted); }\n\n.say { margin: 0; padding: 22px 26px; border-radius: 16px; border: 1px solid var(--teal-edge); background: var(--teal-wash); font-size: 27px; line-height: 1.32; font-weight: 500; position: relative; }\n.say::before { content: \"FALA\"; display: block; font-family: var(--display); font-size: 13px; letter-spacing: 0.22em; color: var(--teal); margin-bottom: 6px; }\n.say.small { font-size: 22px; }\n.say .slot { color: var(--teal); border-bottom: 2px dashed var(--teal-edge); }\n.says { display: grid; gap: 12px; }\n\n.do, .dont { display: grid; gap: 10px; list-style: none; margin: 0; padding: 0; }\n.do li, .dont li { display: grid; grid-template-columns: 26px minmax(0, 1fr); gap: 12px; align-items: start; font-size: 19px; color: var(--muted); }\n.do li::before, .dont li::before { width: 26px; height: 26px; border-radius: 50%; display: grid; place-items: center; font-family: var(--ui); font-size: 13px; font-weight: 700; margin-top: 2px; }\n.do li::before { content: \"✓\"; background: var(--teal); color: var(--teal-ink); }\n.dont li::before { content: \"✕\"; background: var(--red); color: #fff; }\n.dont li { color: var(--fg); }\n.dontbox { padding: 16px 20px; border-radius: 14px; border: 1px solid var(--red-edge); background: var(--red-wash); display: grid; gap: 8px; }\n.dontbox .kicker { color: var(--red); }\n\n.example { padding: 18px 22px; border-radius: 14px; border: 1px solid var(--line); background: var(--card); display: grid; gap: 6px; }\n.example .kicker { color: var(--faint); }\n.example p { margin: 0; font-size: 20px; font-style: italic; color: var(--fg); }\n\n/* fórmula do rótulo */\n.formula { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }\n.formula div { padding: 14px 16px; border-radius: 12px; border: 1px dashed var(--teal-edge); display: grid; gap: 2px; min-width: 0; }\n.formula b { font-family: var(--display); font-weight: 400; font-size: 24px; color: var(--teal); letter-spacing: 0.04em; }\n.formula span { font-family: var(--ui); font-size: 13px; color: var(--muted); }\n\n/* ciclo da dor */\n.loop { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; counter-reset: q; }\n.loop div { position: relative; padding: 16px; border-radius: 12px; background: var(--card); border: 1px solid var(--line); font-size: 19px; line-height: 1.3; font-weight: 500; min-width: 0; }\n.loop div::after { content: \"→\"; position: absolute; right: -14px; top: 50%; transform: translateY(-50%); width: 20px; height: 20px; border-radius: 50%; background: var(--bg); color: var(--teal); font-family: var(--ui); font-size: 12px; display: grid; place-items: center; z-index: 1; }\n.loop div:last-child::after { content: \"↺\"; }\n.grid2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }\n.box { padding: 18px 20px; border-radius: 14px; border: 1px solid var(--line); background: var(--card); display: grid; gap: 8px; align-content: start; min-width: 0; }\n.box h3 { margin: 0; font-family: var(--display); font-weight: 400; font-size: 26px; letter-spacing: 0.03em; line-height: 1; }\n.box p { margin: 0; color: var(--muted); font-size: 18.5px; }\n.box q { color: var(--fg); quotes: \"“\" \"”\"; }\n\n/* mesinha */\n.mesa { display: grid; gap: 0; margin-top: 4px; }\n.tampo { height: 22px; border-radius: 10px; background: linear-gradient(90deg, var(--teal-edge), var(--teal), var(--teal-edge)); box-shadow: 0 10px 40px rgba(45, 212, 191, 0.18); }\n.pernas { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }\n.perna { display: grid; grid-template-rows: auto 1fr; justify-items: center; min-width: 0; }\n.perna i { width: 10px; height: 46px; background: linear-gradient(var(--teal), var(--teal-edge)); border-radius: 0 0 4px 4px; }\n.perna .box { width: 100%; text-align: left; border-color: var(--teal-edge); }\n.perna .box b { font-family: var(--display); font-weight: 400; font-size: 40px; line-height: 0.9; color: var(--teal); }\n.perna .box p { color: var(--fg); font-size: 19px; }\n.perna .box .ok { font-family: var(--display); letter-spacing: 0.12em; color: var(--teal); font-size: 16px; }\n.cai { text-align: center; font-family: var(--display); font-size: 30px; letter-spacing: 0.04em; margin-top: 14px; }\n.steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; counter-reset: s; }\n.steps > li { counter-increment: s; display: grid; grid-template-columns: 44px minmax(0, 1fr); gap: 14px; align-items: start; }\n.steps > li::before { content: counter(s); font-family: var(--display); font-size: 34px; line-height: 1; color: var(--teal); text-align: center; border: 1px solid var(--teal-edge); border-radius: 12px; padding: 6px 0 2px; }\n.steps h3 { margin: 4px 0 4px; font-family: var(--display); font-weight: 400; font-size: 28px; letter-spacing: 0.03em; line-height: 1; }\n.steps p { margin: 0; color: var(--muted); font-size: 19px; }\n.trailer { display: inline-flex; align-items: center; gap: 8px; font-family: var(--ui); font-size: 13px; color: var(--teal); border: 1px solid var(--teal-edge); border-radius: 999px; padding: 4px 10px; margin-top: 6px; }\n\n/* escada */\n.ladder { display: grid; gap: 8px; }\n.step { display: grid; grid-template-columns: 150px 220px minmax(0, 1fr); gap: 16px; align-items: center; padding: 14px 18px; border-radius: 12px; border: 1px solid var(--line); background: var(--card); }\n.step .price { font-family: var(--display); font-size: 38px; line-height: 1; color: var(--teal); letter-spacing: 0.02em; font-variant-numeric: tabular-nums; }\n.step .when { font-family: var(--ui); font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--faint); }\n.step .line { font-size: 19px; line-height: 1.35; }\n.step:nth-child(1) { margin-right: 54px; }\n.step:nth-child(2) { margin-right: 36px; }\n.step:nth-child(3) { margin-right: 18px; }\n.step.bonus { border-color: var(--teal-edge); background: var(--teal-wash); }\n.tablewrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 14px; }\ntable { width: 100%; border-collapse: collapse; font-family: var(--ui); font-size: 14px; font-variant-numeric: tabular-nums; min-width: 560px; }\nth, td { text-align: left; padding: 11px 14px; border-bottom: 1px solid var(--line); white-space: nowrap; }\nth { font-weight: 600; color: var(--faint); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }\ntr:last-child td { border-bottom: 0; }\ntd.save { color: var(--teal); font-weight: 600; }\n.note { font-family: var(--ui); font-size: 13px; color: var(--faint); margin: 0; }\n\n/* objeções */\n.jump { display: flex; flex-wrap: wrap; gap: 8px; }\n.jump a { font-family: var(--ui); font-size: 13px; text-decoration: none; padding: 6px 12px; border-radius: 999px; border: 1px solid var(--line); color: var(--muted); }\n.jump a:hover { border-color: var(--teal-edge); color: var(--fg); }\n.objs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }\n.obj { padding: 20px 22px; border-radius: 16px; border: 1px solid var(--line); background: var(--card); display: grid; gap: 10px; align-content: start; min-width: 0; scroll-margin-top: 24px; }\n.obj:target { border-color: var(--teal-edge); background: var(--teal-wash); }\n.obj header { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 12px; align-items: baseline; }\n.obj header b { font-family: var(--display); font-weight: 400; font-size: 34px; line-height: 1; color: var(--teal); }\n.obj h3 { margin: 0; font-family: var(--display); font-weight: 400; font-size: 28px; letter-spacing: 0.03em; line-height: 1; }\n.obj .resp { margin: 0; font-size: 19.5px; line-height: 1.42; }\n.obj .resp em { font-style: normal; color: var(--teal); }\n.obj ol { margin: 0; padding-left: 22px; display: grid; gap: 6px; font-size: 19px; }\n.obj ol li::marker { color: var(--teal); font-family: var(--display); }\n.obj .tip { font-family: var(--ui); font-size: 13px; color: var(--muted); border-top: 1px solid var(--line); padding-top: 10px; }\n.obj.wide { grid-column: 1 / -1; }\n\n/* depois do sim */\n.after-yes { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; counter-reset: a; }\n.after-yes div { counter-increment: a; padding: 16px 18px; border-radius: 14px; border: 1px solid var(--line); background: var(--card); display: grid; gap: 6px; align-content: start; min-width: 0; }\n.after-yes div::before { content: counter(a); font-family: var(--display); font-size: 30px; line-height: 1; color: var(--teal); }\n.after-yes b { font-family: var(--display); font-weight: 400; font-size: 24px; letter-spacing: 0.03em; line-height: 1; }\n.after-yes span { font-size: 17.5px; color: var(--muted); line-height: 1.38; }\n\nfooter { border-top: 1px solid var(--line); }\nfooter .wrap { padding-block: 24px 40px; font-family: var(--ui); font-size: 12.5px; color: var(--faint); display: flex; flex-wrap: wrap; gap: 8px 24px; justify-content: space-between; }\n\n@media (max-width: 1100px) {\n  .closer { grid-template-columns: repeat(4, minmax(0, 1fr)); }\n  .closer a:nth-child(5) { border-left: 0; }\n  .closer a:nth-child(n+5) { border-top: 1px solid var(--line); }\n  .step { grid-template-columns: 130px minmax(0, 1fr); }\n  .step .line { grid-column: 1 / -1; }\n  .after-yes { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .loop { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .loop div::after { display: none; }\n}\n@media (max-width: 900px) {\n  .layout { grid-template-columns: minmax(0, 1fr); gap: 16px; padding-top: 0; }\n  .nav { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 5; display: flex; gap: 6px; overflow-x: auto; padding-block: 10px; background: rgba(10, 10, 10, 0.94); margin-inline: calc(-1 * max(16px, env(safe-area-inset-left, 0px))); padding-inline: max(16px, env(safe-area-inset-left, 0px)); border-bottom: 1px solid var(--line); }\n  .nav .label, .nav .rule { display: none; }\n  .nav a { flex: none; grid-template-columns: auto auto; padding: 6px 12px; font-size: 16px; border-color: var(--line); }\n  .nav a b { font-size: 18px; }\n}\n@media (max-width: 720px) {\n  body { font-size: 18px; }\n  .closer { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .closer a:nth-child(odd) { border-left: 0; }\n  .closer a:nth-child(n+3) { border-top: 1px solid var(--line); }\n  .num { font-size: 72px; }\n  .say { font-size: 22px; padding: 18px 20px; }\n  .formula, .grid2, .pernas, .objs, .after-yes, .loop { grid-template-columns: minmax(0, 1fr); }\n  .perna i { display: none; }\n  .tampo { display: none; }\n  .step { grid-template-columns: minmax(0, 1fr); gap: 6px; }\n  .step:nth-child(n) { margin-right: 0; }\n}\n@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }\n</style>\n</head>\n<body>\n<div class=\"band\">ROTEIRO NOVO · TIME COMERCIAL · <a href=\"/roteiro-sales-call-atual\" style=\"color:#fff\">VER A ANÁLISE DO ROTEIRO DE HOJE</a></div>\n\n<header class=\"hero\">\n  <div class=\"wrap\">\n    <div class=\"brand\">CANAL DO ANFITRIÃO</div>\n    <div class=\"pills\">\n      <span class=\"pill\"><span class=\"dot\"></span>Call de 30 min no Teams</span>\n      <span class=\"pill red\">Etapas do CLOSER</span>\n    </div>\n    <h1>O roteiro<br><span class=\"t\">da call</span></h1>\n    <p class=\"lede\">O vendedor primeiro pergunta e escuta. <strong>Só mostra a comunidade depois que o lead disse onde está, onde quer chegar e o que está no caminho.</strong></p>\n    <nav class=\"closer\" aria-label=\"As 8 etapas\">\n      <a href=\"#e1\"><b>1</b><span>Clarificar</span></a>\n      <a href=\"#e2\"><b>2</b><span>Rotular</span></a>\n      <a href=\"#e3\"><b>3</b><span>Ciclo da dor</span></a>\n      <a href=\"#e4\"><b>4</b><span>Transição</span></a>\n      <a href=\"#e5\"><b>5</b><span>Vender a viagem</span></a>\n      <a href=\"#e6\"><b>6</b><span>Fechamento</span></a>\n      <a href=\"#e7\"><b>7</b><span>Objeções</span></a>\n      <a href=\"#e8\"><b>8</b><span>Depois do sim</span></a>\n    </nav>\n  </div>\n</header>\n\n<div class=\"wrap layout\">\n  <nav class=\"nav\" aria-label=\"Etapas da call\">\n    <span class=\"label\">Etapas</span>\n    <a href=\"#e1\"><b>1</b>Clarificar</a>\n    <a href=\"#e2\"><b>2</b>Rotular</a>\n    <a href=\"#e3\"><b>3</b>Ciclo da dor</a>\n    <a href=\"#e4\"><b>4</b>Transição</a>\n    <a href=\"#e5\"><b>5</b>Vender a viagem</a>\n    <a href=\"#e6\"><b>6</b>Fechamento</a>\n    <a href=\"#e7\"><b>7</b>Objeções</a>\n    <a href=\"#e8\"><b>8</b>Depois do sim</a>\n    <div class=\"rule\">Pergunta e escuta <strong>antes</strong> de mostrar. A comunidade só entra na etapa 5.</div>\n  </nav>\n\n  <main>\n    <!-- 1 -->\n    <section class=\"stage\" id=\"e1\">\n      <div class=\"stage-head\"><span class=\"num\">1</span><div><span class=\"kicker\">Clarificar</span><h2>Por que a pessoa <span class=\"t\">está aqui</span></h2></div></div>\n      <div class=\"says\">\n        <p class=\"say\">O que te fez entrar na lista de espera e agendar essa chamada?</p>\n        <p class=\"say small\">Me conta mais.</p>\n      </div>\n      <ul class=\"do\">\n        <li>Depois da pergunta, só escuta. Quando ela parar de falar, “me conta mais”.</li>\n        <li>Chega com a ficha do Téo e não repete as perguntas de cadastro.</li>\n      </ul>\n      <div class=\"dontbox\">\n        <span class=\"kicker\">Nessa etapa, não</span>\n        <ul class=\"dont\">\n          <li>Nada de comunidade, de Rômulo ou de preço.</li>\n          <li>A pergunta “você conhece o Rômulo?” saiu do roteiro.</li>\n        </ul>\n      </div>\n    </section>\n\n    <!-- 2 -->\n    <section class=\"stage\" id=\"e2\">\n      <div class=\"stage-head\"><span class=\"num\">2</span><div><span class=\"kicker\">Rotular</span><h2>Devolver o problema <span class=\"t\">nas palavras dela</span></h2></div></div>\n      <p class=\"say\">Deixa eu ver se entendi: hoje você <span class=\"slot\">[onde está]</span>, quer chegar em <span class=\"slot\">[meta]</span>, e o que está no caminho é <span class=\"slot\">[problema]</span>. É isso?</p>\n      <div class=\"formula\" aria-hidden=\"true\">\n        <div><b>Onde está</b><span>a situação de hoje</span></div>\n        <div><b>Meta</b><span>onde quer chegar</span></div>\n        <div><b>Problema</b><span>o que está no caminho</span></div>\n      </div>\n      <div class=\"example\">\n        <span class=\"kicker\">Exemplo real, call de 03/11</span>\n        <p>“Hoje vocês estão construindo 12 lofts em Foz, querem que eles rodem sozinhos pra vocês poderem viajar, e o que está no caminho é que você nunca mexeu com Airbnb e tem medo de errar no preço. É isso?”</p>\n      </div>\n      <ul class=\"do\"><li>Se ela corrigir, rotula de novo até ouvir “é isso”.</li></ul>\n    </section>\n\n    <!-- 3 -->\n    <section class=\"stage\" id=\"e3\">\n      <div class=\"stage-head\"><span class=\"num\">3</span><div><span class=\"kicker\">Visão geral</span><h2>O ciclo <span class=\"t\">da dor</span></h2></div></div>\n      <p class=\"intro\">Pergunte em sequência e repita até ela dizer que é só isso.</p>\n      <div class=\"loop\">\n        <div>O que você já tentou até agora pra resolver isso?</div>\n        <div>E como foi?</div>\n        <div>O que você gostou? E o que não gostou?</div>\n        <div>Tentou mais alguma coisa?</div>\n      </div>\n      <div class=\"grid2\">\n        <div class=\"box\"><h3>O que ela gostou vira ponte</h3><p><q>Se você gostou disso, vai adorar…</q> Do que ela odiou, o vendedor não fala nada parecido.</p></div>\n        <div class=\"box\"><h3>Quem decide e como quer</h3><p><q>Alguém decide isso junto com você?</q></p><p><q>Você quer aprender a fazer ou prefere que alguém faça por você?</q></p></div>\n        <div class=\"box\"><h3>Munição pro preço</h3><p><q>Qual é a diária média hoje? Quantas noites por mês fica ocupado?</q> Se o imóvel ainda não roda: <q>Qual diária você espera cobrar?</q></p><p>E a situação: imóvel pronto, em obra, alugado no fixo, quantos imóveis.</p></div>\n        <div class=\"box\"><h3>Ache a perna bamba</h3><p><q>Chega mensagem de hóspede e não fecha, ou nem chega?</q></p><p><q>Você muda o preço na mão, no automático ou deixa fixo?</q></p><p>Na hora de vender a viagem, demore mais na perna fraca.</p></div>\n      </div>\n    </section>\n\n    <!-- 4 -->\n    <section class=\"stage\" id=\"e4\">\n      <div class=\"stage-head\"><span class=\"num\">4</span><div><span class=\"kicker\">Transição</span><h2>Pedir licença <span class=\"t\">pra mostrar</span></h2></div></div>\n      <p class=\"say\">Acho que você vai gostar do que a gente tem. Posso te mostrar?</p>\n      <div class=\"dontbox\"><span class=\"kicker\">Saiu do roteiro</span><ul class=\"dont\"><li>O combinado dos “dois sentimentos”.</li></ul></div>\n    </section>\n\n    <!-- 5 -->\n    <section class=\"stage\" id=\"e5\">\n      <div class=\"stage-head\"><span class=\"num\">5</span><div><span class=\"kicker\">Vender a viagem</span><h2>Resultado, <span class=\"t\">não módulo</span></h2></div></div>\n      <p class=\"intro\">Fale do resultado: calendário cheio, 5 estrelas, o Pix caindo, viajar enquanto o imóvel roda. Sem tour pelos módulos. E chame o A5E de <strong>comunidade</strong>, não de curso: as aulas gravadas, o grupo e os encontros fazem parte dela.</p>\n      <ol class=\"steps\">\n        <li>\n          <div>\n            <h3>Trailer do A5E</h3>\n            <p>Compartilhe a tela com o som do computador, antes dos pilares. Logo depois, uma frase sobre o Rômulo:</p>\n            <span class=\"trailer\">▶ 3min46</span>\n          </div>\n        </li>\n      </ol>\n      <p class=\"say small\">O Rômulo começou em 2016 alugando no Airbnb um quartinho do apartamento onde ele morava, pra ajudar a pagar o aluguel. Hoje ele administra mais de 70 imóveis.</p>\n      <ol class=\"steps\" start=\"2\" style=\"counter-reset: s 1\">\n        <li><div><h3>A mesinha de 3 pernas</h3><p>Com um “Faz sentido?” depois de cada perna.</p></div></li>\n      </ol>\n      <p class=\"say small\">Pra um imóvel de temporada dar certo, ele é como uma mesinha de 3 pernas.</p>\n      <div class=\"mesa\" aria-label=\"A mesinha de 3 pernas\">\n        <div class=\"tampo\"></div>\n        <div class=\"pernas\">\n          <div class=\"perna\"><i></i><div class=\"box\"><b>1</b><p>Um anúncio que chama a atenção e converte interessados em hóspedes.</p><span class=\"ok\">Faz sentido?</span></div></div>\n          <div class=\"perna\"><i></i><div class=\"box\"><b>2</b><p>A configuração perfeita pra você virar um queridinho do algoritmo e ser mais impulsionado.</p><span class=\"ok\">Faz sentido?</span></div></div>\n          <div class=\"perna\"><i></i><div class=\"box\"><b>3</b><p>Entregar uma ótima experiência pra receber 5 estrelas, e aí o ciclo virtuoso continua acontecendo.</p><span class=\"ok\">Faz sentido?</span></div></div>\n        </div>\n        <p class=\"cai\">“Se uma perna não estiver boa, <span class=\"t\">a mesa inteira cai.</span>”</p>\n      </div>\n      <ol class=\"steps\" start=\"3\" style=\"counter-reset: s 2\">\n        <li><div><h3>Comunidade e lives</h3><p>Logo depois da mesinha.</p></div></li>\n      </ol>\n      <p class=\"say small\">E você não faz isso sozinho: tem a comunidade no WhatsApp, com proprietários do Brasil inteiro, e as lives com o Rômulo pra tirar dúvida.</p>\n      <ul class=\"do\">\n        <li>Explique cada perna com as suas palavras, sem passar vídeo. Uma imagem do Rômulo ajuda, mas não é obrigatória.</li>\n        <li>Os casos de alunos ficam para depois.</li>\n      </ul>\n    </section>\n\n    <!-- 6 -->\n    <section class=\"stage\" id=\"e6\">\n      <div class=\"stage-head\"><span class=\"num\">6</span><div><span class=\"kicker\">Fechamento</span><h2>Primeiro o resumo, <span class=\"t\">depois o preço</span></h2></div></div>\n      <div class=\"says\">\n        <p class=\"say\">Então, resumindo: você entra na comunidade com as aulas gravadas, o grupo de WhatsApp com o Rômulo dentro e as lives mensais pra tirar dúvida.</p>\n        <p class=\"say\">O investimento é R$ 2.997, ou 12x de R$ 299,70. E você tem 14 dias de garantia. A lei dá 7, a gente dá 14: é o dobro. Se não for o que eu te disse, devolvemos 100%, sem precisar explicar nada. Bora começar hoje?</p>\n      </div>\n      <ul class=\"do\"><li>Qualquer resposta que não seja “sim” vai para as objeções (etapa 7).</li></ul>\n\n      <div class=\"box\" style=\"background:transparent;border:0;padding:0\">\n        <span class=\"kicker\">Escada de preço</span>\n        <p>Cada degrau vem com aprovação e prazo.</p>\n      </div>\n      <div class=\"ladder\" aria-label=\"Escada de preço\">\n        <div class=\"step\"><span class=\"price\">R$ 2.997</span><span class=\"when\">Sempre o primeiro</span><span class=\"line\">O fechamento acima.</span></div>\n        <div class=\"step\"><span class=\"price\">R$ 2.797</span><span class=\"when\">Objeção de preço (cupom)</span><span class=\"line\">“Tenho um cupom que deixa em R$ 2.797. Como o cupom não é perpétuo, ele vale até amanhã às 13h.”</span></div>\n        <div class=\"step\"><span class=\"price\">R$ 2.497</span><span class=\"when\">Só com uma trava concreta</span><span class=\"line\">“Conversei com a minha equipe e consegui aprovar R$ 2.497, válido até amanhã às 13h.”</span></div>\n        <div class=\"step bonus\"><span class=\"price\">Bônus</span><span class=\"when\">Pediu mais desconto</span><span class=\"line\">Não baixa mais: oferece o curso de Booking de bônus.</span></div>\n      </div>\n\n      <div class=\"box\" style=\"background:transparent;border:0;padding:0\">\n        <span class=\"kicker\">Reclamou dos juros? Menos parcelas</span>\n      </div>\n      <div class=\"tablewrap\">\n        <table>\n          <thead><tr><th>Preço à vista</th><th>12x (total)</th><th>6x (total)</th><th>4x (total)</th><th>6x economiza</th></tr></thead>\n          <tbody>\n            <tr><td>R$ 2.997 (tabela)</td><td>R$ 299,70 (R$ 3.596)</td><td>R$ 551,83 (R$ 3.311)</td><td>R$ 804,79 (R$ 3.219)</td><td class=\"save\">R$ 285</td></tr>\n            <tr><td>R$ 2.797 (cupom)</td><td>R$ 279,70 (R$ 3.356)</td><td>R$ 515,00 (R$ 3.090)</td><td>R$ 751,08 (R$ 3.004)</td><td class=\"save\">R$ 266</td></tr>\n            <tr><td>R$ 2.497 (aprovação)</td><td>R$ 249,70 (R$ 2.996)</td><td>R$ 459,76 (R$ 2.759)</td><td>R$ 670,52 (R$ 2.682)</td><td class=\"save\">R$ 237</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <p class=\"note\">Taxa da Eduzz de 2,92% ao mês. Confira no checkout antes de usar.</p>\n    </section>\n\n    <!-- 7 -->\n    <section class=\"stage\" id=\"e7\">\n      <div class=\"stage-head\"><span class=\"num\">7</span><div><span class=\"kicker\">Objeções</span><h2>As 11 que <span class=\"t\">mais aparecem</span></h2></div></div>\n      <p class=\"intro\">As 10 primeiras estão na ordem do que mais aparece nas conversas. A 11ª entrou depois e é a 5ª mais comum.</p>\n      <nav class=\"jump\" aria-label=\"Ir para a objeção\">\n        <a href=\"#o1\">Preço</a><a href=\"#o2\">Momento</a><a href=\"#o3\">Vou pensar</a><a href=\"#o4\">YouTube</a><a href=\"#o5\">Cônjuge ou sócio</a><a href=\"#o6\">Serve pro meu caso?</a><a href=\"#o7\">Juros</a><a href=\"#o8\">Façam por mim</a><a href=\"#o9\">Confiança</a><a href=\"#o10\">Já fiz curso</a><a href=\"#o11\">Não tenho tempo</a>\n      </nav>\n      <div class=\"objs\">\n        <article class=\"obj\" id=\"o1\">\n          <header><b>1</b><h3>Preço</h3></header>\n          <p class=\"resp\"><em>Lógica:</em> “12x de R$ 299,70 é menos que uma diária sua de R$ [diária dela] por mês.”</p>\n          <p class=\"resp\"><em>Prova:</em> o Danilo era barbeiro havia 18 anos, fez o curso e em 2 meses fez uns R$ 18 mil. Hoje tem um apartamento em Ubatuba e dois com sócios no Guarujá. “Pra ganhar R$ 1.000 eu tinha que cortar 20 cabelos. Hoje a cobertura é R$ 1.000 a diária.”</p>\n          <p class=\"tip\">Condição: 12x, boleto parcelado, dois cartões e a escada de preço. Quando chegarem outros casos, use o mais parecido com o lead.</p>\n        </article>\n        <article class=\"obj\" id=\"o2\">\n          <header><b>2</b><h3>Momento (obra, bebê, viagem, mês que vem)</h3></header>\n          <p class=\"resp\">“Quanto isso é importante pra você? A obra é justamente o melhor momento: você estuda agora e abre já certo.”</p>\n          <p class=\"tip\">Se não fechar, marca a retomada numa data.</p>\n        </article>\n        <article class=\"obj\" id=\"o3\">\n          <header><b>3</b><h3>Vou pensar</h3></header>\n          <p class=\"resp\">“Você acha que vai melhor com isso do que sem? Chega mais rápido sozinha ou com a gente? Tem como pagar?”</p>\n          <p class=\"tip\">Depois, em voz mais baixa: “O que você tem medo que aconteça?”</p>\n        </article>\n        <article class=\"obj\" id=\"o4\">\n          <header><b>4</b><h3>YouTube ou lives grátis</h3></header>\n          <p class=\"resp\">“O que você faz hoje te dá o resultado que você tem hoje.”</p>\n          <p class=\"resp\">“Nas lives e no YouTube o Rômulo mostra o quê fazer. Na comunidade ele mostra o como, tintim por tintim, e você pergunta no grupo quando travar.”</p>\n        </article>\n        <article class=\"obj wide\" id=\"o5\">\n          <header><b>5</b><h3>Cônjuge ou sócio</h3></header>\n          <p class=\"resp\"><em>Melhor ainda:</em> chamar o cônjuge para a call já na marcação. Se não veio, as seis falas, nesta ordem:</p>\n          <ol>\n            <li>“E se ele não deixar?”</li>\n            <li>“Do que ele seria contra?”</li>\n            <li>“Ele sabe que você está tentando resolver isso? Ele aprova ficar como está? Então por que seria contra resolver?”</li>\n            <li>“Acho que você está pedindo permissão quando precisa de apoio.”</li>\n            <li>“Daqui a 5 anos, se não fizer, quem você vai culpar?”</li>\n            <li>“Entra hoje. Se em casa ele não topar, você tem 14 dias e recebe tudo de volta.”</li>\n          </ol>\n        </article>\n        <article class=\"obj\" id=\"o6\">\n          <header><b>6</b><h3>Serve pro meu caso?</h3></header>\n          <p class=\"resp\"><em>Diagnóstico:</em> de 1 a 5 imóveis, A5E. Com mais imóveis ou gestão para terceiros, Gigantes. Uma recomendação só.</p>\n          <p class=\"resp\"><em>Imóvel longe:</em> “Na comunidade o Rômulo mostra um imóvel em Balneário Camboriú, a 600 km da casa dele, rodando sem ele lá.”</p>\n          <p class=\"resp\"><em>Imóvel simples:</em> “Hóspede valoriza mais funcionalidade e limpeza do que luxo.”</p>\n        </article>\n        <article class=\"obj\" id=\"o7\">\n          <header><b>7</b><h3>Juros</h3></header>\n          <p class=\"resp\">“O juros não é nosso, é da Eduzz. Mas dá pra pagar bem menos: em 6x fica R$ 551,83 por mês, uns R$ 285 a menos que no 12x. E no Pix à vista não tem juros.”</p>\n          <p class=\"tip\">Valores de 12x, 6x e 4x na tabela da etapa 6.</p>\n        </article>\n        <article class=\"obj\" id=\"o8\">\n          <header><b>8</b><h3>Quero que façam por mim</h3></header>\n          <p class=\"resp\">“Até pra isso você precisa entender o mínimo, pra saber o que cobrar. Te garanto: só de estar lá no grupo, cercado de pessoas falando disso o tempo todo, e com o Rômulo respondendo a turma e você, você já aprende. Seis meses lá e você começa a entender várias dinâmicas pra ter mais resultado.”</p>\n        </article>\n        <article class=\"obj\" id=\"o9\">\n          <header><b>9</b><h3>Confiança</h3></header>\n          <p class=\"resp\">“Faz sentido desconfiar, tem muito golpe por aí. O pagamento é pela Eduzz, você tem 14 dias de garantia com 100% de volta, e eu te mostro o grupo funcionando agora.”</p>\n        </article>\n        <article class=\"obj\" id=\"o10\">\n          <header><b>10</b><h3>Já fiz curso e não serviu</h3></header>\n          <p class=\"resp\">“Pior que um investimento ruim é deixar ele te impedir de fazer um bom. O primeiro namoro da escola não deu certo e você não desistiu de namorar.”</p>\n        </article>\n        <article class=\"obj\" id=\"o11\">\n          <header><b>11</b><h3>Não tenho tempo</h3></header>\n          <p class=\"resp\">“Hoje, quanto tempo por semana você gasta com o imóvel? Respondendo hóspede, resolvendo limpeza, mexendo em preço? Normalmente a falta de tempo vem justamente de fazer tudo sem processo. As aulas são gravadas, você assiste quando, onde e sempre que quiser, 20 minutinhos por dia. E o que você aprende ali (mensagem automática, fechadura eletrônica, rotina de limpeza) é o que te devolve tempo. E mesmo na semana mais corrida: só de estar lá no grupo, cercado de pessoas falando disso o tempo todo, e com o Rômulo respondendo a turma e você, você já aprende. Faz sentido?”</p>\n        </article>\n      </div>\n    </section>\n\n    <!-- 8 -->\n    <section class=\"stage\" id=\"e8\">\n      <div class=\"stage-head\"><span class=\"num\">8</span><div><span class=\"kicker\">Reforçar depois do sim</span><h2>O sim <span class=\"t\">não é o fim</span></h2></div></div>\n      <div class=\"says\">\n        <p class=\"say small\">Me manda o comprovante que a minha equipe já libera os bônus.</p>\n        <p class=\"say small\">Decisão certa, porque <span class=\"slot\">[a meta dela, nas palavras dela]</span>.</p>\n      </div>\n      <ul class=\"do\"><li>O link de pagamento vai durante a call.</li><li>Depois, o Téo recebe o aluno, repete a meta dele e passa os primeiros passos:</li></ul>\n      <div class=\"after-yes\">\n        <div><b>Entrar no grupo</b><span>E se apresentar.</span></div>\n        <div><b>Pesquisa de entrada</b><span>Diagnóstico refeito a cada 6 meses para medir as histórias de sucesso.</span></div>\n        <div><b>Módulo inicial</b><span>“Abre o seu anúncio do lado da aula e já vai mexendo. Só não muda mil coisas ao mesmo tempo: uma por vez, pra saber o que funcionou.”</span></div>\n        <div><b>Acompanhamento</b><span>O Téo acompanha o aluno depois da entrada.</span></div>\n      </div>\n    </section>\n  </main>\n</div>\n\n<footer>\n  <div class=\"wrap\">\n    <span>Fonte: roteiro novo da call de vendas, versão de 04/11/2026.</span>\n    <span>Canal do Anfitrião · uso interno do time comercial</span>\n  </div>\n</footer>\n\n<script>\n(function () {\n  var links = Array.prototype.slice.call(document.querySelectorAll('.nav a'));\n  var stages = links.map(function (a) { return document.querySelector(a.getAttribute('href')); });\n  function update() {\n    var y = window.scrollY + window.innerHeight * 0.3;\n    var idx = 0;\n    for (var i = 0; i < stages.length; i++) { if (stages[i] && stages[i].offsetTop <= y) idx = i; }\n    links.forEach(function (a, i) {\n      var on = i === idx;\n      a.classList.toggle('on', on);\n      if (on) a.setAttribute('aria-current', 'step'); else a.removeAttribute('aria-current');\n    });\n    var cur = links[idx];\n    var nav = cur && cur.parentElement;\n    if (nav && nav.scrollWidth > nav.clientWidth) {\n      var left = cur.offsetLeft - nav.clientWidth / 2 + cur.clientWidth / 2;\n      if (Math.abs(nav.scrollLeft - left) > 40) nav.scrollLeft = left;\n    }\n  }\n  window.addEventListener('scroll', update, { passive: true });\n  window.addEventListener('resize', update);\n  update();\n})();\n</script>\n</body>\n</html>\n";
